	zassert_equal(rc, 1, "Expected successful submission to system workqueue, got %d", rc);

	/* Let the system workqueue thread run the work item.
	 * The test thread is cooperative, so it needs to yield.
	 */
	k_sleep(K_TICKS(1));

	/* Verify that the counter for the system workqueue was incremented. */
	zassert_equal(system_counter(), 1, "System workqueue counter not incremented");
	zassert_equal(k_work_busy_get(&common_work), 0, "Work item still busy after completion");

	/* Consume the semaphore given by the counter_handler. */
	rc = k_sem_take(&sync_sem, K_NO_WAIT);
	zassert_equal(rc, 0, "Failed to take sync_sem after work completion");
